VirtualDir PatchManager::GetModificationLoadRoot(bool sdmc) const {
    const auto lookup = [&](u64 id) {
        return sdmc ? fs_controller.GetSDMCModificationLoadRoot(id)
                    : fs_controller.GetModificationLoadRoot(id);
    };
    auto own_root = lookup(title_id);
    if (!parent_title_id) {
        return own_root;
    }
    std::vector<VirtualDir> roots{std::move(own_root), lookup(*parent_title_id)};
    std::erase(roots, nullptr);
    return LayeredVfsDirectory::MakeLayeredDirectory(std::move(roots));
}

std::vector<std::string> PatchManager::GetDisabledAddons() const {
    auto disabled = Settings::values.disabled_addons[title_id];
    if (parent_title_id) {
        const auto& inherited = Settings::values.disabled_addons[*parent_title_id];
        disabled.insert(disabled.end(), inherited.begin(), inherited.end());
    }
    return disabled;
}

